import { useCallback, useMemo } from 'react'
import { GqlResult } from 'uniswap/src/data/types'
import { CurrencyInfo } from 'uniswap/src/features/dataApi/types'
import { CurrencyId } from 'uniswap/src/types/currency'
import { currencyIdToAddress, currencyIdToChain } from 'uniswap/src/utils/currencyId'
import { SafetyLevel } from 'uniswap/src/data/graphql/uniswap-data-api/__generated__/types-and-hooks'
import { useUserTokens } from 'uniswap/src/contexts/UserTokensContext'

/**
 * Returns token projects including user's imported tokens.
 */
export function useTokenProjects(currencyIds: CurrencyId[]): GqlResult<CurrencyInfo[]> {
  const { userAddedTokens } = useUserTokens()
  
  const formattedData = useMemo(() => {
    const currencyInfos: CurrencyInfo[] = []
    
    // Process each requested currencyId
    for (const currencyId of currencyIds) {
      try {
        const address = currencyIdToAddress(currencyId)
        const chainId = currencyIdToChain(currencyId)
        
        if (!address || !chainId) continue
        
        // Check if this token exists in user's imported tokens
        const userToken = userAddedTokens.find(
          token => token.chainId === chainId && 
          token.address.toLowerCase() === address.toLowerCase()
        )
        
        if (userToken) {
          currencyInfos.push({
            currency: userToken,
            currencyId,
            safetyLevel: SafetyLevel.MediumWarning, // Mark imported tokens with warning
            logoUrl: null,
          })
        }
      } catch (error) {
        // Skip invalid currency IDs
        console.warn('Invalid currencyId format:', currencyId, error)
        continue
      }
    }
    
    return currencyInfos
  }, [currencyIds, userAddedTokens])

  const retry = useCallback(() => {
    // No-op since we're not making any API calls
  }, [])

  return useMemo(
    () => ({ 
      data: formattedData, 
      loading: false, 
      refetch: retry, 
      error: undefined 
    }),
    [formattedData, retry],
  )
}
