// V2 pool types (stable vs volatile)
export const ABSTRACT_V2_POOL_TYPES = [
  { stable: false, label: 'volatile' },
  { stable: true, label: 'stable' },
]

export function getAbstractContracts(chainId: UniverseChainId) {
  return ABSTRACT_CONTRACTS[chainId]
}

export function getAbstractSubgraphs(chainId: UniverseChainId) {
  return ABSTRACT_SUBGRAPHS[chainId]
}

export function isAbstractChain(chainId?: number): chainId is UniverseChainId.Sepolia | UniverseChainId.Mainnet {
  return chainId === UniverseChainId.Sepolia || chainId === UniverseChainId.Mainnet
}

// Default to Abstract Testnet for anonymous users
export function getDefaultAbstractChainId(): UniverseChainId {
  return UniverseChainId.Sepolia // Chain ID 11124 (Abstract Testnet)
}