import { useMemo } from 'react'
import { useTranslation } from 'react-i18next'
import { Flex, Text, TouchableArea } from 'ui/src'
import { AlertTriangle } from 'ui/src/components/icons/AlertTriangle'
import { ExternalLink } from 'ui/src/components/icons/ExternalLink'
import { TokenLogo } from 'uniswap/src/components/CurrencyLogo/TokenLogo'
import { CurrencyInfo } from 'uniswap/src/features/dataApi/types'
import { UniverseChainId } from 'uniswap/src/features/chains/types'
import { ExplorerDataType, getExplorerLink } from 'uniswap/src/utils/linking'
import { openUri } from 'uniswap/src/utils/linking'
import { shortenAddress } from 'utilities/src/addresses'

interface ImportTokenWarningProps {
  currencyInfo: CurrencyInfo
  onCancel: () => void
  onImport: () => void
}

export function ImportTokenWarning({ 
  currencyInfo, 
  onCancel, 
  onImport 
}: ImportTokenWarningProps): JSX.Element {
  const { t } = useTranslation()
  const { currency } = currencyInfo

  const explorerLink = useMemo(() => {
    return getExplorerLink(
      currency.chainId,
      currency.address,
      ExplorerDataType.TOKEN
    )
  }, [currency.chainId, currency.address])

  const handleViewOnExplorer = () => {
    if (explorerLink) {
      openUri(explorerLink)
    }
  }

  return (
    <Flex gap="$spacing16" p="$spacing16">
      <Flex row alignItems="center" gap="$spacing12">
        <AlertTriangle color="$statusWarning" size="$icon.24" />
        <Text variant="subheading2" color="$statusWarning">
          {t('tokens.selector.importToken.title')}
        </Text>
      </Flex>

      <Flex alignItems="center" gap="$spacing12">
        <TokenLogo
          chainId={currency.chainId as UniverseChainId}
          name={currency.name}
          symbol={currency.symbol}
          url={currencyInfo.logoUrl}
          size={40}
        />
        <Flex grow>
          <Text variant="subheading2">{currency.name}</Text>
          <Text variant="body3" color="$neutral2">
            {currency.symbol} • {shortenAddress(currency.address)}
          </Text>
        </Flex>
      </Flex>

      <Flex gap="$spacing8">
        <Text variant="body3" color="$neutral2">
          {t('tokens.selector.importToken.warning')}
        </Text>
        <Text variant="body3" color="$neutral2">
          • {t('tokens.selector.importToken.warning.risk1')}
        </Text>
        <Text variant="body3" color="$neutral2">
          • {t('tokens.selector.importToken.warning.risk2')}
        </Text>
        <Text variant="body3" color="$neutral2">
          • {t('tokens.selector.importToken.warning.risk3')}
        </Text>
      </Flex>

      {explorerLink && (
        <TouchableArea onPress={handleViewOnExplorer}>
          <Flex row alignItems="center" gap="$spacing8" p="$spacing8">
            <ExternalLink color="$accent1" size="$icon.16" />
            <Text variant="buttonLabel3" color="$accent1">
              {t('tokens.selector.importToken.viewOnExplorer')}
            </Text>
          </Flex>
        </TouchableArea>
      )}

      <Flex row gap="$spacing12" pt="$spacing8">
        <Flex grow>
          <TouchableArea 
            onPress={onCancel}
            backgroundColor="$surface3"
            borderRadius="$rounded12"
            p="$spacing12"
          >
            <Text variant="buttonLabel2" textAlign="center">
              {t('common.button.cancel')}
            </Text>
          </TouchableArea>
        </Flex>
        <Flex grow>
          <TouchableArea 
            onPress={onImport}
            backgroundColor="$statusWarning"
            borderRadius="$rounded12"
            p="$spacing12"
          >
            <Text variant="buttonLabel2" textAlign="center" color="$statusWarningContrast">
              {t('tokens.selector.importToken.import')}
            </Text>
          </TouchableArea>
        </Flex>
      </Flex>
    </Flex>
  )
}