"use strict";
import { useQuery } from "@tanstack/react-query";
import { Contract } from "@ethersproject/contracts";
import { BigNumber } from "@ethersproject/bignumber";
import { CurrencyAmount, Token } from "@uniswap/sdk-core";
import { Pool as V3Pool, Position as V3PositionSDK } from "@uniswap/v3-sdk";
import { Pair } from "@uniswap/v2-sdk";
import JSBI from "jsbi";
import { useAccount } from "hooks/useAccount";
import { useEthersProvider } from "hooks/useEthersProvider";
import { useMemo } from "react";
import ERC20_ABI from "uniswap/src/abis/erc20.json";
import NonfungiblePositionManagerJson from "@uniswap/v3-periphery/artifacts/contracts/NonfungiblePositionManager.sol/NonfungiblePositionManager.json";
import { getAbstractContracts } from "uniswap/src/constants/abstractContracts";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { PositionStatus, ProtocolVersion } from "@uniswap/client-pools/dist/pools/v1/types_pb";
function getV3PositionStatus(currentTick, tickLower, tickUpper, hasLiquidity) {
  if (!hasLiquidity) {
    return PositionStatus.CLOSED;
  }
  if (currentTick >= tickLower && currentTick <= tickUpper) {
    return PositionStatus.IN_RANGE;
  } else {
    return PositionStatus.OUT_OF_RANGE;
  }
}
const { abi: NFTPositionManagerABI } = NonfungiblePositionManagerJson;
const MULTICALL3_ADDRESS = "0xcA11bde05977b3631167028862bE2a173976CA11";
const MULTICALL3_ABI = [
  {
    inputs: [{ components: [{ name: "target", type: "address" }, { name: "callData", type: "bytes" }], name: "calls", type: "tuple[]" }],
    name: "aggregate",
    outputs: [{ name: "blockNumber", type: "uint256" }, { name: "returnData", type: "bytes[]" }],
    stateMutability: "payable",
    type: "function"
  }
];
async function fetchAllPoolData(userAddress) {
  console.log("\u{1F504} Fetching pool data...");
  try {
    const requests = [
      fetch("https://subgraph.satsuma-prod.com/bdd23fa2967b/mss/v2-testnet/api", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          query: `{
            pairs(first: 1000, orderBy: createdAtTimestamp, orderDirection: desc) {
              id token0 { id symbol decimals name } token1 { id symbol decimals name }
              reserve0 reserve1 totalSupply stable
            }
          }`
        })
      }),
      fetch("https://subgraph.satsuma-prod.com/bdd23fa2967b/mss/aborean-finance-v3-abstract-testnet/api", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          query: `{
            pools(first: 1000) {
              id token0 { id symbol decimals name } token1 { id symbol decimals name }
              tickSpacing liquidity sqrtPrice tick
            }
          }`
        })
      })
    ];
    if (userAddress) {
      requests.push(
        fetch("https://subgraph.satsuma-prod.com/bdd23fa2967b/mss/abx-3-gauges/api", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            query: `query($user: String!) {
              gaugeStakes(where: { user: $user }) {
                id
                user
                amount
                gauge {
                  id
                  pool
                }
              }
            }`,
            variables: { user: userAddress.toLowerCase() }
          })
        })
      );
    }
    const responses = await Promise.all(requests);
    const [v2Response, v3Response, gaugeResponse] = responses;
    const [v2Data, v3Data, gaugeData] = await Promise.all([
      v2Response.json().catch(() => ({ data: { pairs: [] } })),
      v3Response.json().catch(() => ({ data: { pools: [] } })),
      gaugeResponse ? gaugeResponse.json().catch(() => ({ data: { gaugeStakes: [] } })) : Promise.resolve({ data: { gaugeStakes: [] } })
    ]);
    const result = {
      v2Pools: v2Data.data?.pairs || [],
      v3Pools: v3Data.data?.pools || [],
      gaugeStakes: gaugeData.data?.gaugeStakes || []
    };
    console.log(`\u2705 Fetched ${result.v2Pools.length} V2 + ${result.v3Pools.length} V3 pools + ${result.gaugeStakes.length} gauge stakes`);
    return result;
  } catch (error) {
    console.error("\u274C Pool data fetch failed:", error);
    return { v2Pools: [], v3Pools: [], gaugeStakes: [] };
  }
}
function usePoolData(userAddress) {
  return useQuery({
    queryKey: ["pool-data-simple", userAddress],
    queryFn: () => fetchAllPoolData(userAddress),
    staleTime: 6e4,
    // 1 minute
    refetchInterval: 12e4,
    // 2 minutes
    retry: (failureCount, error) => {
      if (error?.message?.includes("429")) return failureCount < 2;
      return failureCount < 3;
    },
    retryDelay: (attemptIndex) => Math.min(1e3 * 2 ** attemptIndex, 3e4)
  });
}
function calculateV2Amounts(userBalance, totalSupply, reserve0, reserve1) {
  const parseDecimalString = (value) => {
    if (!value.includes(".")) {
      return BigNumber.from(value + "000000000000000000");
    }
    const [whole, decimal] = value.split(".");
    const paddedDecimal = decimal.padEnd(18, "0").substring(0, 18);
    return BigNumber.from(whole + paddedDecimal);
  };
  const userBN = BigNumber.from(userBalance);
  const totalBN = parseDecimalString(totalSupply);
  const reserve0BN = parseDecimalString(reserve0);
  const reserve1BN = parseDecimalString(reserve1);
  if (totalBN.eq(0)) return { amount0: "0", amount1: "0" };
  const amount0 = userBN.mul(reserve0BN).div(totalBN);
  const amount1 = userBN.mul(reserve1BN).div(totalBN);
  return { amount0: amount0.toString(), amount1: amount1.toString() };
}
export function useSimpleAbstractPositions({
  address,
  chainIds,
  positionStatuses,
  protocolVersions
}) {
  const account = useAccount();
  const chainId = chainIds && chainIds.filter((c) => c != null)[0] || UniverseChainId.Sepolia;
  const provider = useEthersProvider({ chainId });
  const contracts = getAbstractContracts(chainId);
  const walletAddress = address || account.address;
  const { data: poolData, isLoading: poolsLoading } = usePoolData(walletAddress);
  const positionsQuery = useQuery({
    queryKey: ["positions-simple", walletAddress, chainId, !!poolData],
    queryFn: async () => {
      if (!walletAddress || !provider || !poolData) return [];
      const positions = [];
      try {
        const multicall = new Contract(MULTICALL3_ADDRESS, MULTICALL3_ABI, provider);
        if (!multicall) return [];
        if (poolData.v2Pools.length > 0 && (!protocolVersions || protocolVersions.includes(ProtocolVersion.V2))) {
          const erc20Interface = new Contract("0x0000000000000000000000000000000000000000", ERC20_ABI, provider).interface;
          const v2Calls = poolData.v2Pools.map((pool) => ({
            target: pool.id,
            callData: erc20Interface.encodeFunctionData("balanceOf", [walletAddress])
          }));
          const batchSize = 100;
          for (let i = 0; i < v2Calls.length; i += batchSize) {
            const batch = v2Calls.slice(i, i + batchSize);
            const batchPools = poolData.v2Pools.slice(i, i + batchSize);
            try {
              const [, results] = await multicall.callStatic.aggregate(batch);
              results.forEach((result, idx) => {
                try {
                  const balance = erc20Interface.decodeFunctionResult("balanceOf", result)[0];
                  if (balance.gt(0)) {
                    const pool = batchPools[idx];
                    const { amount0, amount1 } = calculateV2Amounts(
                      balance.toString(),
                      pool.totalSupply,
                      pool.reserve0,
                      pool.reserve1
                    );
                    const token0 = new Token(chainId, pool.token0.id, parseInt(pool.token0.decimals), pool.token0.symbol, pool.token0.name);
                    const token1 = new Token(chainId, pool.token1.id, parseInt(pool.token1.decimals), pool.token1.symbol, pool.token1.name);
                    const liquidityToken = new Token(chainId, pool.id, 18, "LP", "Liquidity Provider Token");
                    const currency0Amount = CurrencyAmount.fromRawAmount(token0, amount0);
                    const currency1Amount = CurrencyAmount.fromRawAmount(token1, amount1);
                    const pair = new Pair(currency0Amount, currency1Amount);
                    positions.push({
                      poolId: pool.id,
                      chainId,
                      version: ProtocolVersion.V2,
                      liquidity: balance.toString(),
                      liquidityAmount: CurrencyAmount.fromRawAmount(liquidityToken, balance.toString()),
                      // Add liquidityAmount for Remove Liquidity
                      status: PositionStatus.IN_RANGE,
                      currency0Amount,
                      currency1Amount,
                      liquidityToken,
                      pair,
                      // Add V2 pair for ratio calculations
                      feeTier: void 0,
                      // V2 doesn't use feeTier
                      v4hook: void 0,
                      owner: void 0,
                      poolType: pool.stable ? "stable" : "volatile"
                      // Add pool type from subgraph
                    });
                  }
                } catch (e) {
                  console.warn("V2 invalid result:", e);
                }
              });
            } catch (e) {
              console.warn("V2 batch failed:", e);
            }
          }
        }
        if (contracts?.nonfungiblePositionManager && (!protocolVersions || protocolVersions.includes(ProtocolVersion.V3))) {
          const nftManager = new Contract(contracts.nonfungiblePositionManager, NFTPositionManagerABI, provider);
          try {
            const balance = await nftManager.balanceOf(walletAddress);
            if (balance.gt(0)) {
              const tokenIdCalls = [];
              for (let i = 0; i < balance.toNumber(); i++) {
                tokenIdCalls.push({
                  target: contracts.nonfungiblePositionManager,
                  callData: nftManager.interface.encodeFunctionData("tokenOfOwnerByIndex", [walletAddress, i])
                });
              }
              const [, tokenIdResults] = await multicall.callStatic.aggregate(tokenIdCalls);
              const tokenIds = tokenIdResults.map((result) => {
                const decoded = nftManager.interface.decodeFunctionResult("tokenOfOwnerByIndex", result);
                return decoded[0].toString();
              });
              const positionCalls = tokenIds.map((tokenId) => ({
                target: contracts.nonfungiblePositionManager,
                callData: nftManager.interface.encodeFunctionData("positions", [tokenId])
              }));
              const [, positionResults] = await multicall.callStatic.aggregate(positionCalls);
              positionResults.forEach((result, idx) => {
                try {
                  const positionData = nftManager.interface.decodeFunctionResult("positions", result);
                  const positionTickSpacing = positionData[4].toString();
                  const matchingPool = poolData.v3Pools.find(
                    (pool) => pool.tickSpacing === positionTickSpacing && (pool.token0.id.toLowerCase() === positionData[2].toLowerCase() && pool.token1.id.toLowerCase() === positionData[3].toLowerCase() || pool.token0.id.toLowerCase() === positionData[3].toLowerCase() && pool.token1.id.toLowerCase() === positionData[2].toLowerCase())
                  );
                  if (matchingPool && positionData.length >= 12) {
                    const token0 = new Token(chainId, positionData[2], parseInt(matchingPool.token0.decimals), matchingPool.token0.symbol, matchingPool.token0.name);
                    const token1 = new Token(chainId, positionData[3], parseInt(matchingPool.token1.decimals), matchingPool.token1.symbol, matchingPool.token1.name);
                    try {
                      const tickSpacing = parseInt(matchingPool.tickSpacing);
                      const feeMap = { 1: 100, 50: 500, 100: 500, 200: 3e3, 2e3: 1e4 };
                      const fee = feeMap[tickSpacing] || 3e3;
                      const pool = new V3Pool(
                        token0,
                        token1,
                        fee,
                        JSBI.BigInt(matchingPool.sqrtPrice),
                        JSBI.BigInt(matchingPool.liquidity),
                        parseInt(matchingPool.tick)
                      );
                      const position = new V3PositionSDK({
                        pool,
                        liquidity: positionData[7].toString(),
                        tickLower: positionData[5],
                        tickUpper: positionData[6]
                      });
                      const hasLiquidity = BigNumber.from(positionData[7]).gt(0);
                      const currentTick = parseInt(matchingPool.tick);
                      const positionStatus = getV3PositionStatus(
                        currentTick,
                        positionData[5],
                        positionData[6],
                        hasLiquidity
                      );
                      positions.push({
                        poolId: matchingPool.id,
                        chainId,
                        tokenId: tokenIds[idx],
                        version: ProtocolVersion.V3,
                        liquidity: positionData[7].toString(),
                        tickLower: positionData[5].toString(),
                        tickUpper: positionData[6].toString(),
                        status: positionStatus,
                        currency0Amount: position.amount0,
                        currency1Amount: position.amount1,
                        pool,
                        // Add V3 pool for ratio calculations
                        position,
                        // Add V3 position for detailed calculations
                        feeTier: fee,
                        tickSpacing,
                        v4hook: void 0,
                        owner: walletAddress
                      });
                    } catch (e) {
                      console.error(`Failed to calculate V3 position ${tokenIds[idx]}:`, e);
                    }
                  }
                } catch (e) {
                  console.warn(`V3 position ${idx} failed:`, e);
                }
              });
            }
          } catch (e) {
            console.warn("V3 positions failed:", e);
          }
        }
        if (poolData.gaugeStakes.length > 0) {
          console.log(`\u{1F3AF} [GAUGE POSITIONS] Found ${poolData.gaugeStakes.length} gauge stakes for user ${walletAddress}`);
          for (const stake of poolData.gaugeStakes) {
            try {
              const poolAddress = stake.gauge.pool.toLowerCase();
              const v2Pool = poolData.v2Pools.find((pool) => pool.id.toLowerCase() === poolAddress);
              if (v2Pool && (!protocolVersions || protocolVersions.includes(ProtocolVersion.V2))) {
                const { amount0, amount1 } = calculateV2Amounts(
                  stake.amount,
                  v2Pool.totalSupply,
                  v2Pool.reserve0,
                  v2Pool.reserve1
                );
                const token0 = new Token(chainId, v2Pool.token0.id, parseInt(v2Pool.token0.decimals), v2Pool.token0.symbol, v2Pool.token0.name);
                const token1 = new Token(chainId, v2Pool.token1.id, parseInt(v2Pool.token1.decimals), v2Pool.token1.symbol, v2Pool.token1.name);
                const liquidityToken = new Token(chainId, v2Pool.id, 18, "LP", "Liquidity Provider Token");
                const currency0Amount = CurrencyAmount.fromRawAmount(token0, amount0);
                const currency1Amount = CurrencyAmount.fromRawAmount(token1, amount1);
                const pair = new Pair(currency0Amount, currency1Amount);
                positions.push({
                  poolId: v2Pool.id,
                  chainId,
                  version: ProtocolVersion.V2,
                  liquidity: stake.amount,
                  liquidityAmount: CurrencyAmount.fromRawAmount(liquidityToken, stake.amount),
                  status: PositionStatus.IN_RANGE,
                  currency0Amount,
                  currency1Amount,
                  liquidityToken,
                  pair,
                  feeTier: void 0,
                  v4hook: void 0,
                  owner: walletAddress,
                  poolType: v2Pool.stable ? "stable" : "volatile",
                  // Mark as gauge position
                  isGaugePosition: true,
                  gaugeAddress: stake.gauge.id,
                  gaugeStakeAmount: stake.amount
                });
                console.log(`\u2705 [GAUGE POSITIONS] Created V2 gauge position for pool ${poolAddress}`);
                continue;
              }
              const v3Pool = poolData.v3Pools.find((pool) => pool.id.toLowerCase() === poolAddress);
              if (v3Pool && (!protocolVersions || protocolVersions.includes(ProtocolVersion.V3))) {
                const token0 = new Token(chainId, v3Pool.token0.id, parseInt(v3Pool.token0.decimals), v3Pool.token0.symbol, v3Pool.token0.name);
                const token1 = new Token(chainId, v3Pool.token1.id, parseInt(v3Pool.token1.decimals), v3Pool.token1.symbol, v3Pool.token1.name);
                try {
                  const tickSpacing = parseInt(v3Pool.tickSpacing);
                  const feeMap = { 1: 100, 50: 500, 100: 500, 200: 3e3, 2e3: 1e4 };
                  const fee = feeMap[tickSpacing] || 3e3;
                  const pool = new V3Pool(
                    token0,
                    token1,
                    fee,
                    JSBI.BigInt(v3Pool.sqrtPrice),
                    JSBI.BigInt(v3Pool.liquidity),
                    parseInt(v3Pool.tick)
                  );
                  const position = new V3PositionSDK({
                    pool,
                    liquidity: stake.amount,
                    tickLower: -887220,
                    // Full range
                    tickUpper: 887220
                    // Full range
                  });
                  positions.push({
                    poolId: v3Pool.id,
                    chainId,
                    tokenId: void 0,
                    // Gauge positions don't have NFT token ID
                    version: ProtocolVersion.V3,
                    liquidity: stake.amount,
                    tickLower: "-887220",
                    // Full range
                    tickUpper: "887220",
                    // Full range
                    status: PositionStatus.IN_RANGE,
                    currency0Amount: position.amount0,
                    currency1Amount: position.amount1,
                    pool,
                    position,
                    feeTier: fee,
                    tickSpacing,
                    v4hook: void 0,
                    owner: walletAddress,
                    // Mark as gauge position
                    isGaugePosition: true,
                    gaugeAddress: stake.gauge.id,
                    gaugeStakeAmount: stake.amount
                  });
                  console.log(`\u2705 [GAUGE POSITIONS] Created V3 gauge position for pool ${poolAddress}`);
                } catch (e) {
                  console.error(`Failed to calculate V3 gauge position for pool ${poolAddress}:`, e);
                }
                continue;
              }
              console.warn(`\u2753 [GAUGE POSITIONS] No matching pool found for gauge stake on pool ${poolAddress}`);
            } catch (e) {
              console.error(`Failed to process gauge stake ${stake.id}:`, e);
            }
          }
        }
        return positions;
      } catch (error) {
        console.error("\u274C Position fetch failed:", error);
        return [];
      }
    },
    enabled: !poolsLoading && !!walletAddress && !!provider && !!poolData,
    staleTime: 3e4,
    // 30 seconds
    refetchInterval: 6e4
    // 1 minute
  });
  const filteredPositions = useMemo(() => {
    if (!positionsQuery.data) return [];
    let filtered = positionsQuery.data;
    if (positionStatuses?.length) {
      filtered = filtered.filter((pos) => positionStatuses.includes(pos.status));
    }
    if (protocolVersions?.length) {
      filtered = filtered.filter((pos) => protocolVersions.includes(pos.version));
    }
    return filtered;
  }, [positionsQuery.data, positionStatuses, protocolVersions]);
  return {
    data: {
      pages: [{ positions: filteredPositions }]
    },
    isLoading: poolsLoading || positionsQuery.isLoading,
    isPlaceholderData: positionsQuery.isPlaceholderData,
    refetch: positionsQuery.refetch,
    fetchNextPage: () => {
    },
    hasNextPage: false,
    isFetching: positionsQuery.isFetching
  };
}
