"use strict";
import { useEffect } from "react";
import { writeContract, waitForTransactionReceipt, switchChain } from "@wagmi/core";
import { wagmiConfig } from "components/Web3Provider/wagmiConfig";
const ERC20_ABI = [
  {
    inputs: [
      { internalType: "address", name: "spender", type: "address" },
      { internalType: "uint256", name: "amount", type: "uint256" }
    ],
    name: "approve",
    outputs: [{ internalType: "bool", name: "", type: "bool" }],
    stateMutability: "nonpayable",
    type: "function"
  }
];
async function revokeAllowance(tokenAddress, spenderAddress, chainId) {
  try {
    await switchChain(wagmiConfig, { chainId });
    const hash = await writeContract(wagmiConfig, {
      address: tokenAddress,
      abi: ERC20_ABI,
      functionName: "approve",
      args: [spenderAddress, 0n],
      chainId
    });
    const receipt = await waitForTransactionReceipt(wagmiConfig, { hash });
    if (receipt.status === "success") {
      return hash;
    } else {
      throw new Error(`Transaction failed: ${hash}`);
    }
  } catch (error) {
    throw error;
  }
}
export function useWindowFunctions() {
  useEffect(() => {
    if (typeof window !== "undefined") {
      window.revokeAllowance = revokeAllowance;
    }
  }, []);
}
